/* From Uiverse.io by escannord  - Tags: icon, button, hover, text animation */
.__UIV_SCOPE__ .button {
  --color: rgb(56, 55, 100);
  padding: 1rem 2rem;
  background-color: transparent;
  color: var(--color);
  font-weight: bolder;
  text-transform: uppercase;
  display: flex;
  justify-content: space-around;
  align-items: center;
  cursor: pointer;
  position: relative;
  border-radius: 5px;
}

.__UIV_SCOPE__ .arrow {
  display: inline-flex;
  position: relative;
  width: 30px;
  height: 15px;
  margin-left: 0.5rem;
}

.__UIV_SCOPE__ .arrow::after,
.__UIV_SCOPE__ .arrow::before {
  content: "";
  display: inline-block;
  position: absolute;
  border-color: var(--color);
}

.__UIV_SCOPE__ .arrow::after {
  width: 10px;
  height: 0;
  border: 2px solid var(--color);
  top: 50%;
  left: 0;
  transform: translateY(-50%);
}

.__UIV_SCOPE__ .arrow::before {
  width: 10px;
  height: 10px;
  border-top: 4px solid var(--color);
  border-right: 4px solid var(--color);
  left: 3px;
  top: 50%;
  transform: translateY(-50%) rotate(45deg);
}

.__UIV_SCOPE__ .button:hover {
  background-color: var(--color);
  color: white;
}

.__UIV_SCOPE__ .button:hover .arrow {
  transform: translateX(10px);
}

.__UIV_SCOPE__ .button:hover .text {
  transform: translateX(10px);
}

.__UIV_SCOPE__ .button:hover .arrow::after {
  width: 25px;
  border-color: white;
}

.__UIV_SCOPE__ .button:hover .arrow::before {
  left: 15px;
  border-color: white;
}

.__UIV_SCOPE__ .button,
.__UIV_SCOPE__ .text,
.__UIV_SCOPE__ .arrow,
.__UIV_SCOPE__ .arrow::after,
.__UIV_SCOPE__ .arrow::before,
.__UIV_SCOPE__ .button::before,
.__UIV_SCOPE__ .button::after {
  transition: all 0.3s, box-shadow 0.2s;
}

.__UIV_SCOPE__ .button::before {
  content: "";
  position: absolute;
  height: 100%;
  width: 10px;
  border-radius: 5px;
  border: solid 3px var(--color);
  border-right-color: transparent;
  background-color: transparent;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
}

.__UIV_SCOPE__ .button::after {
  content: "";
  position: absolute;
  height: 100%;
  width: 10px;
  border-radius: 5px;
  border: solid 3px var(--color);
  border-left-color: transparent;
  background-color: transparent;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
}

.__UIV_SCOPE__ .button:hover:before,
.__UIV_SCOPE__ .button:hover:after {
  width: 50% !important;
}

.__UIV_SCOPE__ .button:active {
  box-shadow: 0px 0px 0px 7px rgba(79, 78, 105, 0.295);
}
